function classify(n) {
  if (!Number.isInteger(n)) return 'heap';     // non-integers are always HeapNumbers
  const MIN = -(2 ** 31);
  const MAX = 2 ** 31 - 1;    // largest 32-bit signed integer
  if (n >= MIN && n < MAX) return 'smi';
  return 'heap';
}

