diff.code:
// low bit is the tag: 0 = Smi (int in upper bits), 1 = pointer (index into heap[])
const heap = [];

function tagSmi(n) {
  return n << 1;            // shift left, low bit becomes 0
}

function tagPointer(obj) {
  const idx = heap.push(obj) - 1;
  return (idx << 1) | 1;   // low bit 1
}

function isSmi(word) {
  return word & 1 === 0;   // even word -> Smi
}

function untagSmi(word) {
  return word >> 1;
}

function deref(word) {
  return heap[word >> 1];
}
